use crate::domains::rust_perf::PerfRule;

/// Data table, not logic — grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<PerfRule> {
    vec![
        // ── caching: a pure-function-of-geometry artifact rebuilt per
        // layer/per call → memoize at the OWNER's lifetime, keyed on
        // every input ──────────────────────────────────────────────────
        // Source: DFlash2Draft.swift (DFlash2SlidingMaskMemo + the hoist
        // comment, ercumentyildirim / terrapinelf `ff96d1e`).
        PerfRule {
            rule_id: "mask-memo-hoist-to-owner-lifetime".to_string(),
            name: "a pure-function-of-geometry artifact (mask, index table, plan) rebuilt per layer/per call → memoize at the OWNER's lifetime (the engine/drafter struct) keyed on every input — repeated rounds reuse the same value AND the same graph node".to_string(),
            category: "caching".to_string(),
            buggy_code: "pub struct Layer {\n    pub idx: usize,\n}\n\nimpl Layer {\n    // Rebuilds the sliding-window mask on EVERY call — once per layer,\n    // every forward, for identical geometry. Building it per layer\n    // re-ran the same comparison graph once per layer.\n    pub fn mask(&self, ctx: usize, blk: usize, win: usize) -> Vec<i32> {\n        let mut mask = vec![0i32; ctx * blk];\n        for q in 0..ctx {\n            for k in 0..blk {\n                let dist = (q as i64 - k as i64).unsigned_abs() as usize;\n                if q < k || dist > win {\n                    mask[q * blk + k] = i32::MIN;\n                }\n            }\n        }\n        mask\n    }\n}\n\npub struct Engine {\n    pub layers: Vec<Layer>,\n}\n\npub fn forward_naive(e: &Engine, ctx: usize, blk: usize, win: usize) -> usize {\n    let mut total = 0usize;\n    for l in &e.layers {\n        total += l.mask(ctx, blk, win).len();\n    }\n    total\n}".to_string(),
            fixed_code: "// The memo lives with the OWNER (the engine/drafter struct), keyed on\n// EVERY input, so a layer whose inputs differ still gets its own mask;\n// repeated speculative forwards with identical geometry reuse the same\n// value AND the same graph node downstream.\npub struct MaskMemo {\n    key: Option<(usize, usize, usize)>,\n    cached: Vec<i32>,\n}\n\nimpl MaskMemo {\n    pub fn new() -> Self {\n        MaskMemo { key: None, cached: Vec::new() }\n    }\n\n    pub fn mask(&mut self, ctx: usize, blk: usize, win: usize) -> &[i32] {\n        let key = (ctx, blk, win);\n        if self.key != Some(key) {\n            let mut mask = vec![0i32; ctx * blk];\n            for q in 0..ctx {\n                for k in 0..blk {\n                    let dist = (q as i64 - k as i64).unsigned_abs() as usize;\n                    if q < k || dist > win {\n                        mask[q * blk + k] = i32::MIN;\n                    }\n                }\n            }\n            self.key = Some(key);\n            self.cached = mask;\n        }\n        &self.cached\n    }\n}\n\npub struct Engine {\n    pub layers: Vec<usize>,\n    pub memo: MaskMemo,\n}\n\npub fn forward_memo(e: &mut Engine, ctx: usize, blk: usize, win: usize) -> usize {\n    let mut total = 0usize;\n    for _ in 0..e.layers.len() {\n        total += e.memo.mask(ctx, blk, win).len();\n    }\n    total\n}".to_string(),
            context_notes: Some("NotBenchable-by-domain (a mask rebuild is one comparison graph; the win is graph-node reuse + allocation churn — measurable only end-to-end in a speculative-decode loop; the Batch-135 io-annotation class). SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d, DFlash2Draft.swift, verbatim): 'Sliding masks depend only on block geometry. Keep the memo with the drafter so repeated speculative forwards can reuse the same graph (ercumentyildirim / terrapinelf `ff96d1e`).' The memo class is keyed on every input of make(contextLength:blockLength:slidingWindow:isCausal:) so 'a layer whose inputs differ still gets its own mask'; 'Building it per layer re-ran the same comparison graph once per layer.' Also a GRAPH-REUSE enabler, not just an alloc hoist — the same mask array keeps downstream graph caches keyed on it stable. Regime: repeated structures with identical geometry inputs. Anti-regime: inputs that vary per call (the key must include EVERY input); unbounded distinct geometries (cap or evict the memo). Distinct from shared-activation-quantize-memo-per-eval (the per-eval activation memo — value-bound, request-scoped; this is geometry-bound, owner-scoped) and from weight-handle-cache-keyed-by-allocation-identity (B29 — pointer-keys unchanged weights; this keys a DERIVED artifact on its geometry inputs). Cite: @ cfb35b0d — DFlash2Draft.swift (DFlash2SlidingMaskMemo + the hoist comment); Batch 181 / Plan 174 / Research 212.".to_string()),
            // Not benchable: the win is graph-node reuse + allocation churn,
            // measurable only end-to-end in a spec-decode loop.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },

        // ── complexity (measurement honesty #5): the SEAM-WARM side — run
        // the EXACT scored seam once at load on throwaway state so
        // first-use costs never land inside a timed window ─────────────
        // Source: Qwen35DFlash2Assistant.swift (warmTargetPrefill +
        // warmEngineRound; MLXFAST_SEED_PREFILL_WARM=0).
        PerfRule {
            rule_id: "seed-warm-the-scored-seam".to_string(),
            name: "a benchmark/timed window whose seam (exact code path + shapes) runs first INSIDE the window → warm the exact seam at load on throwaway state (fixed pattern, greedy, state released after) — first-use costs otherwise land in every cold process's timed window".to_string(),
            category: "complexity".to_string(),
            buggy_code: "pub struct BenchEngine {\n    pub warm: bool,\n    pub work: u64,\n}\n\n// First-use cost: lazy graph compile + allocator growth, paid INSIDE\n// the first timed iteration of every cold process.\npub fn lazy_graph_compile(e: &mut BenchEngine) {\n    if !e.warm {\n        e.work = e.work.wrapping_add(0x5DEE_CE66);\n        e.warm = true;\n    }\n}\n\npub fn step(e: &mut BenchEngine, tok: u64) -> u64 {\n    e.work = e.work.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(tok);\n    e.work\n}\n\n// The timed window: iteration 0 pays lazy_graph_compile + allocator\n// growth inside the timed loop — nothing before the timed window ran\n// that seam.\npub fn run_window(engine: &mut BenchEngine, tokens: &[u64]) -> Vec<u64> {\n    let mut out = Vec::with_capacity(tokens.len());\n    for &t in tokens {\n        lazy_graph_compile(engine);\n        out.push(step(engine, t));\n    }\n    out\n}".to_string(),
            fixed_code: "pub struct BenchEngine {\n    pub warm: bool,\n    pub work: u64,\n}\n\npub fn lazy_graph_compile(e: &mut BenchEngine) {\n    if !e.warm {\n        e.work = e.work.wrapping_add(0x5DEE_CE66);\n        e.warm = true;\n    }\n}\n\npub fn step(e: &mut BenchEngine, tok: u64) -> u64 {\n    e.work = e.work.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(tok);\n    e.work\n}\n\n// Warm the EXACT scored seam at load: the identical call pattern on a\n// throwaway state, fixed token pattern, greedy — nothing depends on any\n// request's input. State is released after, so the served phases start\n// from the footprint a cold load leaves. Kill-switch: skip when\n// SEED_WARM=0.\npub fn warm_scored_seam() -> bool {\n    if std::env::var(\"SEED_WARM\").ok().as_deref() == Some(\"0\") {\n        return false;\n    }\n    let mut throwaway = BenchEngine { warm: false, work: 0x243F_6A88 };\n    let fixed_pattern: [u64; 4] = [11, 22, 33, 44];\n    for &t in &fixed_pattern {\n        lazy_graph_compile(&mut throwaway);\n        step(&mut throwaway, t);\n    }\n    std::mem::drop(throwaway); // release: the timed window starts cold-footprint\n    true\n}\n\npub fn run_window(engine: &mut BenchEngine, tokens: &[u64]) -> Vec<u64> {\n    warm_scored_seam(); // the load path: the seam's first-use costs leave the window\n    let mut out = Vec::with_capacity(tokens.len());\n    for &t in tokens {\n        lazy_graph_compile(engine);\n        out.push(step(engine, t));\n    }\n    out\n}".to_string(),
            context_notes: Some("NotBenchable decision-content (the fix IS measurement hygiene; the measured numbers are the harm's pricing, not a fixable code shape). SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ cfb35b0d, Qwen35DFlash2Assistant.swift, verbatim): the model-level warms miss the ENGINE round machinery — 'Nothing before the timed window runs that machinery either... So a fresh process paid its first-use costs inside the window's first round: on the local M4 Max that round's early drafter submission took 143-208 ms instead of 36-41 ms and the round 464-534 ms instead of ~358 ms, with +1.2-1.8 G instructions, ~150 page faults and ~+0.13 s of system time in the window, and none of it in any later window of the same process. One engine request of 16 tokens at load removes all of it; a model-level round does not.' And the target seam: 'Nothing before the timed decode phase runs that seam... So every scored window paid the seam's first-use costs inside the timed seed window. On every published leg the seed window reads 30-42 ms slower than the timed prefill of the same 512 tokens, even though it does less work (and ~36 ms on the serial control leg too).' The warm must run the EXACT seam: 'The engine is built the way the benchmark worker builds a DFlash leg (contiguous KV, one stream, the scored seed width in one chunk, fixed depth 15, rectangular verify), over the SERVING model this drafter is bound to, so the same code runs. The prompt is the same fixed token pattern warmTargetPrefill uses, greedy, so nothing depends on any request's input' + 'the caches and recurrent state are fresh and released here... so the served phases start from the footprint a cold load leaves'. Kill-switch MLXFAST_SEED_PREFILL_WARM=0 skips warmTargetPrefill. FAMILY: B177 aa-control-prices-the-fidelity-instrument is the COMPARATOR-side member; THIS is the SEAM-WARM side (the instrument's own warm-up). Distinct from warm-reachable-dispatch-signatures-before-timed-window (B115 — the dispatch-signature axis; this is the seam/engine-round axis); B115 gains a second instance rider this batch (warm per alignment class — AttentionV1 warmVerifyBlock). RIDER (the per-depth-oracle measurement law, same source port notes): 'A speculative round verifies its draft in one forward at M > 1, and MLX dispatches a different kernel there, so the free-run tape can fork from the serial tape at a near-tie' — spec-lane correctness pins must oracle PER DEPTH, never against the serial tape alone (the six per-depth oracles measured byte-identical to each other but DIFFERENT from the serial tape). Cite: @ cfb35b0d — Qwen35DFlash2Assistant.swift (warmTargetPrefill + warmEngineRound); Batch 181 / Plan 174 / Research 212.".to_string()),
            // Not benchable: the fix IS measurement hygiene — no fixable
            // code shape to A/B.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
    ]
}
